mapper.update:
update knowledge_base
set name = #{name},
    description = #{description},
    updated_by = #{updatedBy},
    updated_at = #{updatedAt}
where id = #{id}
  and workspace_id = #{workspaceId}
  and status = 'ACTIVE'
  and deleted_at is null

update knowledge_base
set status = 'ARCHIVED',
    updated_by = #{updatedBy},
    updated_at = #{updatedAt}
where id = #{id}
  and workspace_id = #{workspaceId}
  and status = 'ACTIVE'
  and deleted_at is null

update knowledge_base
set document_count = (
        select count(1)
        from document_asset da
        where da.workspace_id = #{workspaceId}
          and da.kb_id = #{id}
          and da.deleted_at is null
    ),
    segment_count = (
        select coalesce(sum(da.segment_count), 0)
        from document_asset da
        where da.workspace_id = #{workspaceId}
          and da.kb_id = #{id}
          and da.deleted_at is null
    ),
    updated_by = #{updatedBy},
    updated_at = #{updatedAt}
where id = #{id}
  and workspace_id = #{workspaceId}
  and deleted_at is null
